'use client'

import { useActionState } from 'react'

type ContactFormState = {
  error?: string
  success?: boolean
}

const initialState: ContactFormState = {}

export default function ContactForm() {
  const [state, formAction, pending] = useActionState(submitContactMessage, initialState)

  return (
    <div>
      <h2>Contact Us</h2>
      <form action={formAction}>
        <div>
          <label htmlFor="name">Name</label>
          <input type="text" id="name" name="name" required />
        </div>
        <div>
          <label htmlFor="email">Email</label>
          <input type="email" id="email" name="email" required />
        </div>
        <div>
          <label htmlFor="message">Message</label>
          <textarea id="message" name="message" rows={5} required />
        </div>
        {state?.error && (
          <p role="alert" style={{ color: 'red' }}>
            {state.error}
          </p>
        )}
        {state?.success && (
          <p role="status" style={{ color: 'green' }}>
            Thank you! Your message has been sent.
          </p>
        )}
        <button type="submit" disabled={pending}>
          {pending ? 'Sending...' : 'Send Message'}
        </button>
      </form>
    </div>
  )
}

async function submitContactMessage(
  _prevState: ContactFormState,
  formData: FormData
): Promise<ContactFormState> {
  'use server'

  const name = formData.get('name')?.toString().trim()
  const email = formData.get('email')?.toString().trim()
  const message = formData.get('message')?.toString().trim()

  // JavaScript validation: check that all fields are provided
  if (!name || !email || !message) {
    return {
      error: 'All fields are required. Please provide your name, email, and message.',
    }
  }

  // TODO: Save contact message (e.g., to database, send email)
  // For now, we simulate successful submission
  return { success: true }
}

